#!/bin/sh
# Runs every simulation + the script-order check. Needs three@0.147.0:  npm i three@0.147.0  (set NODE_PATH to its node_modules)
cd "$(dirname "$0")/.." || exit 1
fail=0
for t in tests/load_order.check.js tests/syntax.check.js tests/worldstate.sim.js tests/verbs.sim.js tests/vaults.sim.js tests/events.sim.js tests/flight_fps.sim.mjs tests/soccer.sim.js tests/scatter_cull.check.mjs tests/feel.sim.mjs tests/dive.sim.js tests/static_batch.sim.mjs tests/phase2.sim.mjs tests/anim_smoke.check.mjs tests/css_theme.check.js tests/outlaw_hud.check.js tests/hud_mode.sim.js tests/space.sim.mjs tests/camera_flight.sim.mjs tests/space_objects.sim.mjs tests/hitzones.sim.js tests/outlaw_arena.sim.js tests/combatpose.sim.js tests/gunloco.sim.js tests/consumables.sim.js tests/enemyai.sim.js tests/scope.sim.js tests/warden_regress.sim.js tests/warden_core.sim.js tests/warden_phase.sim.js tests/expedition.sim.js tests/warden_retry.sim.js tests/warden_prog.sim.js tests/warden_gear.sim.js tests/warden_island.sim.js tests/warden_ai.sim.js tests/warden_props.sim.js tests/warden_combos.sim.js tests/warden_mx.sim.js tests/warden_fx.sim.js tests/warden_foes.sim.js tests/warden_dungeon.sim.js tests/offline_cache.check.js tests/space_world.sim.mjs tests/boost.sim.mjs tests/decks.sim.js tests/ship.sim.js tests/fleet.sim.js tests/crew.sim.js tests/shipcam.sim.js tests/edge.sim.js tests/flight_vertical.sim.mjs tests/rally_car.sim.js tests/rally_assets.check.js tests/ocean.sim.js tests/surf.sim.js tests/barrage.sim.js tests/echo.sim.js tests/tricks.sim.js tests/styles.sim.js tests/lockon.sim.js tests/monster.sim.js tests/leviathan.sim.js tests/voyage.sim.js tests/seamodes.sim.js tests/landwar.sim.js tests/fires.sim.js tests/shipctl.sim.js tests/combat_peak.sim.js tests/deckhands.sim.js tests/westtown.sim.js tests/nav.sim.js tests/tactics.sim.js tests/boss.sim.js tests/rally_collide.sim.js tests/rally_cars.sim.js tests/rally_items.sim.js tests/rally_track.sim.js tests/rally_track2.sim.js tests/rally_world.sim.js tests/skyraid.sim.js tests/avatar_kit.sim.js tests/avatar_assets.check.js; do
  out=$(node "$t" 2>&1); code=$?
  if [ $code -ne 0 ]; then echo "✗ $t"; echo "$out" | grep -v '^ok' | head -15; fail=1
  else echo "✓ $t  ($(echo "$out" | grep -c '^ok') checks)"; fi
done
exit $fail
